<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>User Management | Radix</title></head><body class="min-h-screen bg-slate-100 p-6 text-slate-900"><main class="mx-auto max-w-6xl"><a href="{{ route('admin.dashboard') }}">← Admin Dashboard</a><h1 class="mt-6 text-3xl font-bold">User Management</h1>@if(session('status'))<p class="mt-4 rounded bg-teal-50 p-3">{{ session('status') }}</p>@endif<form class="mt-6 flex gap-2" method="get"><input name="search" value="{{ $search }}" placeholder="Cari nama, NIM, email" class="flex-1 rounded border p-3"><button class="rounded bg-slate-900 px-4 py-2 text-white">Cari</button></form><section class="mt-6 overflow-x-auto rounded-2xl bg-white p-6"><table class="w-full text-left text-sm"><thead><tr class="border-b"><th class="p-3">User</th><th class="p-3">XP</th><th class="p-3">Topic selesai</th><th class="p-3">Status</th><th class="p-3">Leaderboard</th><th class="p-3">Aksi</th></tr></thead><tbody>@forelse($users as $user)<tr class="border-b"><td class="p-3"><strong>{{ $user->name }}</strong><br>{{ $user->nim }} · {{ $user->email }}</td><td class="p-3">{{ number_format($user->total_xp) }}</td><td class="p-3">{{ $user->completed_topics_count }}</td><td class="p-3">{{ $user->is_active ? 'Aktif' : 'Nonaktif' }}</td><td class="p-3">{{ $user->is_leaderboard_visible ? 'Tampil' : 'Disembunyikan' }}</td><td class="p-3 space-y-2"><form method="post" action="{{ route('admin.users.active', $user) }}">@csrf @method('patch')<button>{{ $user->is_active ? 'Nonaktifkan' : 'Aktifkan' }}</button></form><form method="post" action="{{ route('admin.users.leaderboard', $user) }}">@csrf @method('patch')<button>{{ $user->is_leaderboard_visible ? 'Sembunyikan' : 'Tampilkan' }}</button></form></td></tr>@empty<tr><td colspan="6" class="p-3">User tidak ditemukan.</td></tr>@endforelse</tbody></table>{{ $users->links() }}</section></main></body></html>
